/**
 * Plain-language summary of a model config, generated by switching on
 * architectural features, never on the model. Values are config data, not
 * computed quantities, so they are strings rather than Derived.
 */
import type { AttentionConfig, FfnConfig, MlpConfig, ModelSpec, PositionConfig } from '../types';
import { dtypeLabel, formatCount, formatInt } from './format';

export interface Fact {
  label: string;
  value: string;
  /** Dotted path into the ModelSpec, for source / approximate lookup. */
  path: string;
}

function attention(a: AttentionConfig): string {
  switch (a.kind) {
    case 'MHA':
      return `Multi-head (MHA) · ${a.heads} heads · head dim ${a.headDim}`;
    case 'GQA':
      return `Grouped-query (GQA) · ${a.heads} query / ${a.kvHeads} KV heads · head dim ${a.headDim}`;
    case 'MLA': {
      const q = a.qLoraRank === null ? '' : ` · query latent ${a.qLoraRank}`;
      return `Multi-head latent (MLA) · ${a.heads} heads · KV latent ${a.kvLoraRank} + RoPE key ${a.qkRopeHeadDim}${q}`;
    }
  }
}

function mlp(m: MlpConfig): string {
  const name = m.gated ? (m.activation === 'silu' ? 'SwiGLU' : 'GeGLU') : `${m.activation === 'silu' ? 'SiLU' : 'GELU'} MLP`;
  return `${name} · intermediate ${formatInt(m.interDim)}`;
}

function ffn(f: FfnConfig): string {
  switch (f.kind) {
    case 'dense':
      return mlp(f.mlp);
    case 'moe': {
      const dense = f.leadingDense ? ` · first ${f.leadingDense.layers} layers dense` : '';
      return `Mixture of experts · ${f.routedExperts} routed + ${f.sharedExperts} shared · top-${f.topK} · expert ${mlp(f.expert)}${dense}`;
    }
  }
}

function position(p: PositionConfig, maxPositions: number): string {
  switch (p.kind) {
    case 'learned':
      return `Learned absolute table · ${formatInt(maxPositions)} positions`;
    case 'rope': {
      const theta = `RoPE · θ = ${formatInt(p.theta)}`;
      if (!p.scaling) return theta;
      const kind = p.scaling.kind === 'llama3' ? 'Llama 3 frequency scaling' : 'YaRN';
      return `${theta} · ${kind} ×${p.scaling.factor} from ${formatInt(p.scaling.originalMaxPositions)}`;
    }
  }
}

export function describeConfig(m: ModelSpec): Fact[] {
  const c = m.config;
  return [
    { label: 'Layers', value: formatInt(c.layers), path: 'config.layers' },
    { label: 'Hidden size', value: formatInt(c.hidden), path: 'config.hidden' },
    { label: 'Attention', value: attention(c.attention), path: 'config.attention' },
    { label: 'FFN', value: ffn(c.ffn), path: 'config.ffn' },
    { label: 'Positions', value: position(c.position, c.maxPositions), path: 'config.position' },
    { label: 'Norm', value: `${c.norm.kind} · ε = ${c.norm.eps < 1e-3 ? c.norm.eps.toExponential() : c.norm.eps}`, path: 'config.norm' },
    { label: 'Vocabulary', value: formatInt(c.vocab), path: 'config.vocab' },
    { label: 'Context', value: `${formatInt(c.maxPositions)} tokens`, path: 'config.maxPositions' },
    { label: 'LM head', value: c.tiedEmbeddings ? 'Tied to the token embedding' : 'Separate matrix', path: 'config.tiedEmbeddings' },
    { label: 'Checkpoint', value: dtypeLabel(c.nativeDtype), path: 'config.nativeDtype' },
    { label: 'Tokenizer', value: m.tokenizer.algorithm, path: 'tokenizer' },
  ];
}

export function describeTraining(m: ModelSpec): Fact[] {
  const t = m.training;
  if (!t) return [];
  const facts: Fact[] = [{ label: 'Pretraining tokens', value: formatCount(t.tokens), path: 'training.tokens' }];
  if (t.gpuHours !== undefined) {
    facts.push({ label: 'GPU hours', value: `${formatCount(t.gpuHours)}${t.gpu ? ` on ${t.gpu}` : ''}`, path: 'training.gpuHours' });
  }
  return facts;
}
